package ama.transcript;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Synthetic immutable history checks only; neither these rows nor this verifier issue authority. */
class Task11PublicationWriteHistoryTest {
 static final String MEETING="12345678-1234-4234-8234-123456789ac1",PUB="12345678-1234-4234-8234-123456789abc",FINAL="12345678-1234-4234-8234-123456789abd",TASK="12345678-1234-4234-8234-123456789abe",OP="12345678-1234-4234-8234-123456789abf",EXEC="12345678-1234-4234-8234-123456789ac0",STORE="12345678-1234-4234-8234-123456789ac2";
 static Map<String,Object> row(Object... pairs){var out=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}
 static final class Fixture {
  final Map<String,Object> root=row("id",MEETING,"revision",15L,"ever_published",0L,"stage","PUBLISH_FAILED","lifecycle","ACTIVE","governance_state","ACTIVE");
  final List<Map<String,Object>> pubs=new ArrayList<>(),finals=new ArrayList<>();
  final Map<String,List<Map<String,Object>>> rows=new LinkedHashMap<>();
  final Map<String,String> originals=new TreeMap<>();
  final Map<String,PublicationWriteHistory.ExecutionOriginal> executions=new TreeMap<>();
  final Map<String,Object> manifest=new Task11AcceptanceBindingTest().manifest();
  Fixture(){for(String name:List.of("publication_submission","external_document_mapping","publication_attempt","durable_task","task_attempt","external_operation","external_execution"))rows.put(name,new ArrayList<>());}
  Fixture local(){
   manifest.put("publicationId",PUB);manifest.put("confirmationId",FINAL);manifest.put("meetingId",MEETING);manifest.put("businessKey",PUB+":"+FINAL);manifest.put("storeInstanceId",STORE);manifest.put("requesterId","owner");
   var logical=new TreeMap<String,Object>();logical.put("schema","ama.knowledge-publish.v1");logical.put("domain","KNOWLEDGE_PUBLISH");for(String key:List.of("providerId","publicationId","confirmationId","businessKey","libraryId","folderId","renderArtifact","payloadSha256"))logical.put(key,manifest.get(key));logical.put("sourceManifestHash","e".repeat(64));logical.put("inputFingerprint","f".repeat(64));manifest.put("logicalRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(logical)));manifest.put("executionRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",manifest.get("logicalRequestHash"),"executionNo",1L,"priorProofs",List.of()))));
   String original=new String(ControlledKnowledgeClient.canonical(manifest),StandardCharsets.UTF_8);originals.put(TASK,original);var spec=JdbcPublicationService.spec(manifest,new Task11AcceptanceBindingTest().budget());
   pubs.add(row("id",PUB,"meeting_id",MEETING,"confirmation_id",FINAL,"business_key",PUB+":"+FINAL,"provider_id",manifest.get("providerId"),"library_id",manifest.get("libraryId"),"folder_id",manifest.get("folderId"),"state","FAILED","revision",2L));
   finals.add(row("id",FINAL,"meeting_id",MEETING,"meeting_revision",13L,"source_manifest_hash","e".repeat(64),"input_fingerprint","f".repeat(64)));
   rows.get("publication_submission").add(row("task_id",TASK,"publication_id",PUB,"submission_no",1L,"confirmation_id",FINAL,"provider_id",manifest.get("providerId"),"business_key",PUB+":"+FINAL,"library_id",manifest.get("libraryId"),"folder_id",manifest.get("folderId"),"requester_id","owner","logical_request_hash",manifest.get("logicalRequestHash"),"execution_request_hash",manifest.get("executionRequestHash"),"local_state","NEVER_MARKED","local_decided_at","done","local_decided_by","owner","local_reason","TERMINAL_UNMARKED_FAILURE","local_attempt_no",0L,"local_execution_id",null));
   rows.get("durable_task").add(row("id",TASK,"task_type",spec.type(),"pool",spec.pool(),"subject_kind","MEETING","subject_id",MEETING,"producer_key",spec.producerKey(),"input_kind",spec.input().kind(),"input_id",spec.input().id(),"input_fingerprint",spec.inputFingerprint(),"business_version",spec.businessVersion(),"priority",0L,"cancel_epoch",spec.cancelEpoch(),"max_attempts",3L,"attempt",0L,"state","FAILED","output_kind",null,"output_id",null));return this;
  }
  Fixture remote(){local();var s=rows.get("publication_submission").getFirst();s.put("local_state","UNDECIDED");for(String field:List.of("local_decided_at","local_decided_by","local_reason","local_attempt_no","local_execution_id"))s.put(field,null);rows.get("durable_task").getFirst().put("attempt",1L);rows.get("task_attempt").add(row("task_id",TASK,"attempt",1L,"ended_at","done","outcome","FAILED"));rows.get("external_operation").add(row("id",OP,"operation_kind","KNOWLEDGE_PUBLISH","business_key",PUB+":"+FINAL,"subject_kind","MEETING","subject_id",MEETING,"state","FAILED","request_hash",manifest.get("logicalRequestHash"),"current_execution_no",1L,"external_result_present",0L));rows.get("external_execution").add(row("id",EXEC,"operation_id",OP,"execution_no",1L,"task_id",TASK,"request_hash",manifest.get("executionRequestHash"),"state","FAILED","marked_at","marked","task_attempt",1L,"finished_at","done","no_effect_basis","DEFINITIVE_REJECTION","no_effect_verified_at","verified","provider_proof_reference_shape",1L,"no_effect_evidence_present",1L,"proof_store",STORE,"proof_receipt","receipt-"+"a".repeat(32),"proof_digest","b".repeat(64)));rows.get("publication_attempt").add(row("id",EXEC,"publication_id",PUB,"confirmation_id",FINAL,"operation_id",OP,"execution_id",EXEC,"kind","PUBLISH","outcome","FAILED","finished_at","done"));executions.put(EXEC,new PublicationWriteHistory.ExecutionOriginal(originals.get(TASK),"knowledge:"+STORE+":receipt-"+"a".repeat(32)+":"+"b".repeat(64)));return this;}
  void verify(){PublicationWriteHistory.verify(root,pubs,finals,new PublicationGraph.Plan(MEETING,List.of(),List.of(),rows,new Task11AcceptanceBindingTest().budget()),originals,executions);}
 }
 @Test void noPublicationAndCompleteLocalOrRemoteClosurePermitMetadataAdmission(){assertDoesNotThrow(()->new Fixture().verify());assertDoesNotThrow(()->new Fixture().local().verify());assertDoesNotThrow(()->new Fixture().remote().verify());}
 @Test void permanentAndUnresolvedStatesNeverOpenOrdinaryWrites(){for(String state:List.of("READY","RUNNING","RECONCILING","SUCCEEDED","MANUAL_REQUIRED")){var f=new Fixture().remote();f.pubs.getFirst().put("state",state);assertThrows(RuntimeException.class,f::verify,state);}for(String state:List.of("PREPARED","MARKED","UNKNOWN","SUCCEEDED","MANUAL_REQUIRED")){var f=new Fixture().remote();f.rows.get("external_execution").getFirst().put("state",state);assertThrows(RuntimeException.class,f::verify,state);}var f=new Fixture().local();f.root.put("ever_published",1L);assertThrows(RuntimeException.class,f::verify);}
 @Test void missingOrChangedImmutableManifestFinalAndProducerAreRejected(){for(String target:List.of("submission","execution","final","producer","original-set")){var f=new Fixture().remote();switch(target){case "submission"->f.originals.put(TASK,f.originals.get(TASK)+" ");case "execution"->f.executions.put(EXEC,new PublicationWriteHistory.ExecutionOriginal("{}",f.executions.get(EXEC).noEffectEvidence()));case "final"->f.finals.getFirst().put("source_manifest_hash","a".repeat(64));case "producer"->f.rows.get("durable_task").getFirst().put("producer_key","c".repeat(64));default->f.originals.put(OP,"{}");}assertThrows(RuntimeException.class,f::verify,target);}}
 @Test void orphanFamiliesMappingAndUnfinishedAttemptCannotHideBehindFailedHeader(){var f=new Fixture().remote();f.rows.get("external_document_mapping").add(row("publication_id",PUB,"authority_state","WITHDRAWN"));assertThrows(RuntimeException.class,f::verify);f=new Fixture().remote();f.rows.get("task_attempt").getFirst().put("ended_at",null);assertThrows(RuntimeException.class,f::verify);f=new Fixture().remote();var orphan=new LinkedHashMap<>(f.rows.get("durable_task").getFirst());orphan.put("id",OP);orphan.put("input_id",EXEC);f.rows.get("durable_task").add(orphan);assertThrows(RuntimeException.class,f::verify);f=new Fixture().remote();f.pubs.clear();assertThrows(RuntimeException.class,f::verify);}
 @Test void fullDurableEvidenceMustMatchTheAdmittedReference(){var f=new Fixture().remote();f.executions.put(EXEC,new PublicationWriteHistory.ExecutionOriginal(f.originals.get(TASK),"knowledge:unrelated"));assertThrows(RuntimeException.class,f::verify);}
 @Test void orphanExecutionOrAttemptCannotDisappearInTheEmptyPublicationBranch(){var f=new Fixture();f.rows.get("external_execution").add(row("id",EXEC,"operation_id",OP,"task_id",TASK));assertThrows(RuntimeException.class,f::verify);f=new Fixture();f.rows.get("task_attempt").add(row("task_id",TASK,"attempt",1L));assertThrows(RuntimeException.class,f::verify);}
 @Test void shapedRemoteReferenceAndLocalLabelAloneAreNotEnough(){for(String field:List.of("proof_store","proof_receipt","proof_digest","finished_at","task_attempt")){var f=new Fixture().remote();f.rows.get("external_execution").getFirst().put(field,null);assertThrows(RuntimeException.class,f::verify,field);}for(String field:List.of("local_reason","local_decided_at","local_decided_by","local_attempt_no")){var f=new Fixture().local();f.rows.get("publication_submission").getFirst().put(field,field.equals("local_reason")?"ARBITRARY_LABEL":null);assertThrows(RuntimeException.class,f::verify,field);}}
 @Test void mutableOperationCannotPointPastTheCompleteExecutionHistory(){var f=new Fixture().remote();f.rows.get("external_operation").getFirst().put("current_execution_no",2L);assertThrows(RuntimeException.class,f::verify);}
 @Test void mixedRemoteAndLocalHistoryAdmitsOnlyWhenEveryOlderRoundIsClosed(){
  var f=new Fixture().remote();appendLocalSuccessor(f);assertDoesNotThrow(f::verify);
  for(String state:List.of("UNKNOWN","MARKED","SUCCEEDED","MANUAL_REQUIRED")){var changed=new Fixture().remote();appendLocalSuccessor(changed);changed.rows.get("external_execution").getFirst().put("state",state);assertThrows(RuntimeException.class,changed::verify,state);}
 }
 static void appendLocalSuccessor(Fixture f){
  String next="12345678-1234-4234-8234-123456789ad1";var m=new TreeMap<String,Object>(f.manifest);m.put("submissionNo",2L);m.put("executionNo",2L);
  var proofs=List.of(Map.<String,Object>of("executionId",EXEC,"executionRequestHash",f.manifest.get("executionRequestHash"),"receiptId","receipt-"+"a".repeat(32),"proofDigest","b".repeat(64)));m.put("priorProofs",proofs);m.put("bindingTransition",Map.of("schema","ama.controlled-kb-binding-transition.v1","expectedGeneration",1L,"priorProofs",proofs,"newBusinessKey",m.get("businessKey"),"newLogicalRequestHash",m.get("logicalRequestHash")));
  m.put("executionRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",m.get("logicalRequestHash"),"executionNo",2L,"priorProofs",proofs))));
  var spec=JdbcPublicationService.spec(m,new Task11AcceptanceBindingTest().budget());var task=new LinkedHashMap<>(f.rows.get("durable_task").getFirst());task.put("id",next);task.put("producer_key",spec.producerKey());task.put("attempt",0L);f.rows.get("durable_task").add(task);
  var submission=new LinkedHashMap<>(f.rows.get("publication_submission").getFirst());submission.put("task_id",next);submission.put("submission_no",2L);submission.put("execution_request_hash",m.get("executionRequestHash"));submission.put("local_state","NEVER_MARKED");submission.put("local_decided_at","done");submission.put("local_decided_by","owner");submission.put("local_reason","TERMINAL_UNMARKED_FAILURE");submission.put("local_attempt_no",0L);f.rows.get("publication_submission").add(submission);f.originals.put(next,new String(ControlledKnowledgeClient.canonical(m),StandardCharsets.UTF_8));
 }

}